// Parse Cargo.toml and build dependency graph
const content = $binary['data'].toString('utf8');
const lines = content.split('\n');
let inDeps = false;
let inWorkspaceDeps = false;
const deps = {};
let currentCrate = '';

for (const line of lines) {
  if (line.startsWith('[workspace.dependencies]')) {
    inWorkspaceDeps = true;
    continue;
  }
  if (line.startsWith('[')) {
    inWorkspaceDeps = false;
    continue;
  }
  if (inWorkspaceDeps && line.includes('=')) {
    const [name, val] = line.split('=').map(s => s.trim().replace(/"/g, ''));
    deps[name] = val;
  }
}

// Read .meta.yaml projects for cross-repo context
const fs = require('fs');
const path = require('path');
const metaRoot = process.env.META_ROOT;
if (!metaRoot) throw new Error('META_ROOT is required; run envctl env or ask envctl over weave before running this workflow.');
const yamlPath = path.join(metaRoot, '.meta.yaml');
let metaProjects = [];
try {
  const yamlContent = fs.readFileSync(yamlPath, 'utf8');
  // Simple line-based parsing as fallback
  const projectLines = yamlContent.split('\n').filter(l => l.trim().startsWith('-') || (l.startsWith(' ') && !l.includes(':')));
  metaProjects = projectLines.map(l => l.replace(/[- ]/, '').trim()).filter(Boolean);
} catch(e) {
  // If .meta.yaml parsing fails, use known workspace members
}

// Build reverse dependency map for the changed crate
const changedCrate = $json.changed_crate;
const dependents = [];
for (const [crate, val] of Object.entries(deps)) {
  if (val.includes(changedCrate) || crate.toLowerCase() === changedCrate.toLowerCase()) {
    dependents.push(crate);
  }
}

// Transitive closure: find all crates that transitively depend on the changed crate
const visited = new Set();
function traceTransitive(crate, depth = 0) {
  if (depth > 10 || visited.has(crate)) return;
  visited.add(crate);
  for (const [other, val] of Object.entries(deps)) {
    if (val.includes(crate) && !visited.has(other)) {
      traceTransitive(other, depth + 1);
    }
  }
}
traceTransitive(changedCrate);

return {
  json: {
    direct_dependents: dependents,
    transitive_dependents: [...visited],
    meta_projects_context: metaProjects.slice(0, 20),
    graph_built: true
  }
};

// Kahn's algorithm for topological sort
const graph = {};
const inDegree = {};

// Build adjacency from the parsed deps
for (const [crate, val] of Object.entries($json.graph_raw || {})) {
  if (!graph[crate]) graph[crate] = [];
}

const visited = new Set($json.transitive_dependents || []);
const directDeps = $json.direct_dependents || [];

// Simple topo sort: foundation crates first, then dependents
const order = [];
for (const crate of visited) {
  // Foundation crates have fewer deps, go first
  const isFoundation = ['meta_core', 'loop_lib', 'meta_plugin_protocol', 'meta_mcp'].includes(crate);
  order.push({ crate, tier: isFoundation ? 0 : 1 });
}
order.sort((a, b) => a.tier - b.tier);
return { json: { execution_order: order.map(o => o.crate), topo_built: true } };

=const depCount = $json.direct_dependents ? $json.direct_dependents.length : 0;
const transCount = $json.transitive_dependents ? $json.transitive_dependents.length : 0;
const totalAffected = depCount + (transCount - depCount);

let risk = 'Low';
if (totalAffected >= 6) risk = 'Critical';
else if (totalAffected >= 3) risk = 'High';
else if (totalAffected >= 1) risk = 'Medium';

const foundationTiers = ['meta_core', 'loop_lib', 'meta_plugin_protocol', 'meta_mcp'];
const changedCrate = $json.changed_crate;
if (foundationTiers.includes(changedCrate)) risk = totalAffected > 2 ? 'Critical' : 'High';

return { json: { risk_level: risk, affected_repos_count: totalAffected, direct_dependents: $json.direct_dependents || [], transitive_dependents: $json.transitive_dependents || [] } };
